#import <Foundation/Foundation.h>
#import "RuntimeDiagnostics.h"
static void check(BOOL ok,NSString *m){if(!ok){NSLog(@"FAIL %@",m);exit(1);}}
int main(int argc,char **argv){@autoreleasepool{
NSString *root=[NSTemporaryDirectory() stringByAppendingPathComponent:NSUUID.UUID.UUIDString];[NSFileManager.defaultManager createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];
check([TFResolvedOptimization(@{@"optimization":@"debug"}) isEqual:@"-O0"],@"debug");check([TFResolvedOptimization(@{@"optimization":@"release-size"}) isEqual:@"-Os"],@"release");check([TFResolvedOptimization(@{@"optimization":@"release-speed"}) isEqual:@"-O2"],@"release O2");
NSString *source=@"// NSClassFromString(@\"Fake\");\n[cell setValue: ^(id value) { use(value); } forKey:@\"callback\"];\nNSClassFromString(@\"Private\");\nNSString *text = @\"NSClassFromString(Fake)\";\n";NSString *p=[root stringByAppendingPathComponent:@"Tweak.xm"];[source writeToFile:p atomically:YES encoding:NSUTF8StringEncoding error:nil];NSArray *risks=TFRuntimeRisks(root);check(risks.count==2,@"risk counts/comment filtering");check([risks[0][@"line"] intValue]==2,@"line mapping");check([risks isEqual:TFRuntimeRisks(root)],@"idempotent");check([[NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:nil] isEqual:source],@"no writes");NSDictionary *prov=TFBuildProvenance(root,@[@"Tweak.xm"],@{@"optimization":@"debug"},@"Build-test");check([prov[@"inputs"][0][@"sha256"] length]==64,@"source sha256");
NSData *binary=[NSData dataWithContentsOfFile:@(argv[1])];NSDictionary *idx=TFBinaryIndex(binary);check([idx[@"uuid"] length]==36,@"real MachO UUID");check([idx[@"symbols"] count]>0,@"real MachO symbols");
for(NSUInteger n=0;n<MIN(binary.length,1000);n++)check(TFBinaryIndex([binary subdataWithRange:NSMakeRange(0,n)]).count==0,@"truncated MachO");
NSString *dir=[root stringByAppendingPathComponent:@"Build-test"];[NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];[[NSJSONSerialization dataWithJSONObject:@{@"images":@[idx]} options:0 error:nil] writeToFile:[dir stringByAppendingPathComponent:@"symbols.json"] atomically:YES];
NSDictionary *crash=@{@"procName":@"fixture",@"faultingThread":@0,@"usedImages":@[@{@"name":@"fixture.dylib",@"uuid":idx[@"uuid"]}],@"threads":@[@{@"triggered":@YES,@"frames":@[@{@"imageIndex":@0,@"imageOffset":idx[@"symbols"][0][@"offset"]}]}]};NSString *result=TFCrashAnalysis([NSJSONSerialization dataWithJSONObject:crash options:0 error:nil],root);check([result containsString:@"已匹配本机构建"]&&[result containsString:@"最近符号"],@"exact UUID matched");
NSData *real=[NSData dataWithContentsOfFile:@(argv[2])];NSString *actual=TFCrashAnalysis(real,root);check([actual containsString:@"小红果"]&&[actual containsString:@"未匹配本机构建"],@"real ips / no name guessing");check([TFCrashAnalysis([@"{}" dataUsingEncoding:NSUTF8StringEncoding],root) containsString:@"未识别"],@"bad JSON");
[NSFileManager.defaultManager removeItemAtPath:root error:nil];puts("PASS: profiles, provenance, risk suggestions, idempotence, read-only, MachO bounds, UUID matching, real two-part ips");}}
